char *generate_random_password(int length) {
    if (length < 1) {
        return NULL;
    }
    size_t n = sizeof(SYMBOLS) - 1;
    char *buf = malloc((size_t) length + 1);
    for (int idx = 0; idx < length; ++idx) {
        buf[idx] = SYMBOLS[rand() % n];
    }
    buf[length] = '\0';
    for (int i = length - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        char tmp = buf[i];
        buf[i] = buf[j];
