private static void removeEven (int [] k, int n) {
    int counter = 0;
    int i = 0;
    while (i < n) {
        if (k [i] % 2 == 1) {
            k [counter ++] = k [i];
        }
        i ++;
    }
    Arrays.fill (k, counter, n, 0);
}

